   "路上水坑多，接送的时候绕一绕，鞋湿了闷一天难受。",
   "雨水后别急着给孩子减衣服，老话说春捂。厚外套先留一件在车里。",
   "雨鞋闷一天脚容易凉，书包里备双干袜子，湿了能换。",
   "这阵子孩子容易犯困，晚上早点睡，别熬着。",
   "衣服晾不干带着潮味，多备一套换洗的，别硬穿。",
   "家里潮就开窗透透气，别整天关着。风大的时候关上就行。",
   "雨天路滑，接娃的骑车开车都慢点，早出门十分钟不慌。",
