   "门口垫子湿透了就换一块，踩进踩出泥水都带屋里了。",
   "雨鞋脱下来放通风的地方，别直接塞鞋柜，闷着有味。",
   "出门前趴窗看一眼，雨小也把伞带上，回来准用得着。",
   "早上叫孩子起床多留十分钟，雨天被窝里黏，起得慢。",
   "水杯里装点温的，雨天凉得快，到学校喝着还行。",
   "湿鞋别摞一块儿，一双一双摆开，第二天干得利索。",
