   "夏至前后太热，孩子头晕恶心就赶紧停下歇着，别硬扛。",
   "夏至多给孩子吃西瓜黄瓜番茄，当季的解暑补水，比冰饮料强。",
   "夏至后白天渐短，跟孩子说，最长的白天都来了，把劲头用在坚持上。",
   "夏至傍晚凉快了，带孩子下楼走走，回来冲个温水澡，好入睡。",
   "夏至天热，心静下来就好。陪孩子做做拉伸聊聊天，不用非得出大汗。",
   "夏至这天白昼最长，天也黑得晚。孩子在外面玩容易忘了时间，记得喊他回来。",
