   "孩子活动出一身汗，湿衣服别焐着，回家先换下来。",
   "今天立冬，早上先烧壶热水，孩子洗漱别用凉的。",
   "立冬了，孩子脖子上加条围巾，早上出门那会儿风硬。",
   "晚上给孩子被子上再搭条薄的，后半夜凉。",
   "立冬后天黑得早，孩子放学先回家，别在外头磨蹭。",
   "今天立冬，晚上早点让孩子睡，作息跟着往前挪一挪。",
   "天冷了，孩子书包里塞包纸巾，风一吹鼻涕就下来了。",
   "立冬了，秋裤换成加绒的那条，薄的收起来。",
   "家里保温壶灌满，孩子写作业手边有口热水。",
   "立冬了，晚饭给孩子做点热乎的，汤汤水水的吃着暖和。",
   "早上出门前瞄一眼孩子外套拉链，风往领口里钻。",
   "立冬了，孩子手套找出来塞书包侧兜，早上骑车手冷。",
   "家里暖气还没来的话，晚上给孩子被窝里放个热水袋。",
   "立冬了，孩子嘴唇干，家里备支润唇膏搁他书包里。",
   "立冬了，孩子洗澡水温调高些，出来头发擦干再穿衣服。",
   "立冬了，孩子出门前喝口热的再走，肚子里有点底。",
   "天冷孩子胃口好，晚饭别让他吃太撑，夜里睡不安稳。"
