   "小雪前后容易感冒，早晚温差大，增减衣服别偷懒，出汗了赶紧擦干换掉。",
   "小雪要是下雪了，带孩子堆雪人打雪仗，回来喝碗热姜汤。",
   "小雪运动别太猛，快走慢跑跳绳都行，四十分钟以内，冷了进屋歇会儿。",
   "在家跳绳、开合跳，或者陪孩子玩点游戏，冬天屋里也能动起来。",
