   "天冷不是偷懒的理由，能坚持下来的孩子，身上就是有劲儿。",
   "小雪一到，家里炖锅萝卜羊肉，孩子吃完浑身暖和。",
   "暖气一开屋里干，床头放盆水，早上起来嗓子舒服点。",
   "睡前给孩子泡泡脚，水别太烫，十来分钟，睡得沉。",
   "小雪前后要是飘雪了，接孩子早点出门，路上慢点开。",
   "屋里暖气足，孩子的厚被子别急着收，后半夜还是凉。",
   "桌上放个保温杯，孩子自己就想着喝，一天水不断。",
