   "放学那阵天都黑透了，孩子出教室就把薄外套披上，路上风硬。",
   "小雪进家门别急着脱外套，屋里外头温差大，缓一会儿再脱。",
   "睡前把明天要穿的毛衣袜子搁床头，早上孩子自己套上就行。",
