   "小雪这几天的白菜水灵，晚上包顿饺子，孩子吃得快。",
   "睡前把暖水袋塞被窝焐一会儿，孩子钻进去不凉。",
   "手套备两副，丢一只还有一只换，小雪后路上得戴。",
   "润唇膏搁孩子书包侧兜，天冷嘴唇干，他自己会想起来抹。",
   "晚饭煮锅热汤面，孩子进门先喝两口汤，小雪天暖胃。",
   "小雪后屋里干，晚上睡觉前把加湿器打开，孩子嗓子舒服点。",
   "孩子那件薄棉服先别急着收，小雪这几天白天还能穿。",
   "早上出门天还黑着，路上慢点骑，别抢那两分钟。",
   "保温杯换个大的，小雪天孩子喝水少，一天下来没喝几口。",
   "洗完头记得吹干再睡，小雪后夜里凉，别顶着湿头发。",
   "进门先别急着脱外套，屋里屋外温差不小，缓一缓再脱。",
   "拖鞋换双棉的，地砖凉，孩子光脚踩上去容易着凉。",
   "被子上再搭层薄毯，小雪后半夜温度掉得快。",
   "小雪一过，早上叫孩子起床多留五分钟，被窝里先赖一会儿再起。"
