   "屋里暖气烧得干，睡前放盆水或者搭条湿毛巾，嗓子能舒服些。",
   "接送路上有冰的地方别让娃跑，咱手牵着慢慢走就行。",
   "书包里多放一副手套，玩雪湿了随时能换。",
   "天冷了饭菜凉得快，端上桌就让孩子趁热吃，别等。",
